import os
from remotesystem import RemoteSystem
from .objects.mosaiq_core_objects import MosaiqCoreObjects
from .objects.mosaiq_photo_and_diagrams_import_objects import PhotoAndDiagramImport
from interops.libraries.squish_actions import CommonActions
from interops.libraries.desktop import decorators as deco
from interops.libraries.squish_actions.constants import MOSAIQ_APP_NAME

def __find_main_photos_and_diagrams_window() -> bool:
    """Searches for the Photos and Diagrams Import UI Window. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the chart.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(PhotoAndDiagramImport.main_Window) is not None else False

def __find_image_edit_photos_and_diagrams_window() -> bool:
    """Searches for the Image Edit UI from Photos and Diagrams Import workflow. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the chart.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(PhotoAndDiagramImport.imageEdit_Main_Window) is not None else False

def __accept_directory_question_dialog() -> None:
    if CommonActions.find_object(MosaiqCoreObjects.question_Window):
        CommonActions.left_click_object(MosaiqCoreObjects.question_Yes_Button)
        CommonActions.wait_for_object_to_disappear(MosaiqCoreObjects.question_Window)

def __set_image_type_dropdown(imageType: str) -> None:
    CommonActions.left_click_object(PhotoAndDiagramImport.imageEdit_Image_Type_Dropdown)
    CommonActions.press_key_sequence(imageType[0])

def __set_mark_all_as_type_dropdown(markAllType: str) -> None:
    CommonActions.left_click_object(PhotoAndDiagramImport.markAll_Type_Dropdown)
    CommonActions.press_key_sequence(markAllType[0])

def __create_directory_if_does_not_exist(directoryPath: str) -> None:
    rs = RemoteSystem()
    if rs.exists(directoryPath) is False:
        rs.createDirectory(directoryPath)

def __delete_file_if_already_exists_within_directory(locationOfFile: str) -> None:
    rs = RemoteSystem()
    if rs.exists(locationOfFile) is True:
        rs.deleteFile(locationOfFile)

def create_id_photo_directory(imageDirectory: str, imageFile: str) -> str:
    rs = RemoteSystem()
    if rs.exists(os.path.join(imageDirectory, imageFile)) is False:
        raise Exception("Target Image could not be found on Remote System")
    try:
        new_id_folder_path = os.path.join(imageDirectory, "ID_PHOTO")
        __create_directory_if_does_not_exist(new_id_folder_path)

        image_file_path = os.path.join(new_id_folder_path, imageFile)
        __delete_file_if_already_exists_within_directory(image_file_path)

        rs.copy(os.path.join(imageDirectory, imageFile), image_file_path)
        return new_id_folder_path
    except Exception as e:
        print(str(e))

def create_field_site_directory(targetLocation: str, imageDirectory: str) -> str:
    rs = RemoteSystem()
    if rs.exists(targetLocation) is False:
        raise Exception("Target Location path does not exisit on target remote system")
    if rs.exists(imageDirectory) is False:
        raise Exception("Image Directory path does not exisit on target remote system")
    try:
        new_id_folder_path = os.path.join(targetLocation, "FIELD_SITES")
        __create_directory_if_does_not_exist(new_id_folder_path)

        rs.copy(imageDirectory, new_id_folder_path)
        return new_id_folder_path
    except Exception as e:
        print(str(e))

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def change_image_directory(imageDirectory: str) -> None:
    if __find_main_photos_and_diagrams_window():
        CommonActions.left_click_object(PhotoAndDiagramImport.directory_Path_Textbox)
        CommonActions.press_key_sequence_ctrl_a()
        CommonActions.press_delete_key()
        CommonActions.type_in_textfield(PhotoAndDiagramImport.directory_Path_Textbox, imageDirectory)
        CommonActions.press_enter_key()
        __accept_directory_question_dialog()
        CommonActions.wait_for_object_to_disappear(PhotoAndDiagramImport.scanning_For_Images_Pane)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def set_image_as_patient_id_photo(imageFile: str) -> None:
    if __find_main_photos_and_diagrams_window():
        all_image_previews = CommonActions.get_all_objects_by_map(PhotoAndDiagramImport.image_Preview_Object)
        for child_object in all_image_previews:
            CommonActions.double_click_object(child_object)
            if __find_image_edit_photos_and_diagrams_window():
                image_name = CommonActions.get_objects_text_value(PhotoAndDiagramImport.imageEdit_Image_Name_Pane)
                if imageFile in image_name:
                    __set_image_type_dropdown("ID Photo")
                    CommonActions.left_click_object(PhotoAndDiagramImport.imageEdit_OK_Button)
                    break

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def set_images_as_field_site_photos() -> None:
    if __find_main_photos_and_diagrams_window():
        all_image_previews = CommonActions.get_all_objects_by_map(PhotoAndDiagramImport.image_Preview_Object)
        for child_object in all_image_previews:
            CommonActions.double_click_object(child_object)
            if __find_image_edit_photos_and_diagrams_window():
                __set_image_type_dropdown("Fld Setup")
                CommonActions.left_click_object(PhotoAndDiagramImport.imageEdit_OK_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_mark_all_as_import() -> None:
    if __find_main_photos_and_diagrams_window():
        CommonActions.left_click_object(PhotoAndDiagramImport.markAll_Import_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def set_all_images_as_field_setup() -> None:
    if __find_main_photos_and_diagrams_window():
        __set_mark_all_as_type_dropdown("Fld Setup")

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_import_ok_button() -> None:
    if __find_main_photos_and_diagrams_window():
        CommonActions.left_click_object(PhotoAndDiagramImport.oK_Button)